package com.example.battleshipgame.ai;
import com.example.battleshipgame.logic.*;import java.util.*;
public class BattleshipAI {private final Random random=new Random();private final ArrayDeque<int[]> targets=new ArrayDeque<>();public int[]choose(Board b){while(!targets.isEmpty()){int[]p=targets.removeFirst();if(b.get(p[0],p[1])!=Board.Cell.HIT&&b.get(p[0],p[1])!=Board.Cell.MISS)return p;}int r,c;do{r=random.nextInt(Board.SIZE);c=random.nextInt(Board.SIZE);}while(b.get(r,c)==Board.Cell.HIT||b.get(r,c)==Board.Cell.MISS);return new int[]{r,c};}public void learn(int r,int c,ShotResult s){if(s==ShotResult.HIT||s==ShotResult.SUNK)for(int[]d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int nr=r+d[0],nc=c+d[1];if(nr>=0&&nc>=0&&nr<Board.SIZE&&nc<Board.SIZE)targets.addLast(new int[]{nr,nc});}if(s==ShotResult.SUNK)targets.clear();}}
